var(--color-text-secondary);font-size:12px}.task-list{display:grid}.task-row,.case-preview-row,.notice-preview{width:100%;border:0;border-bottom:1px solid var(--color-border);background:transparent;color:var(--color-text);cursor:pointer;text-align:left;font:inherit;transition:background-color 160ms ease,transform 180ms cubic-bezier(.16,1,.3,1)}.task-row{display:grid;grid-template-columns:12px minmax(140px,1.3fr) minmax(120px,1fr) minmax(120px,.7fr) auto;align-items:center;gap:12px;min-height:54px;font-size:13px}.task-row:hover,.case-preview-row:hover,.notice-preview:hover{background:var(--color-accent-soft);transform:translate3d(3px,0,0)}.task-row:active,.case-preview-row:active,.notice-preview:active{transform:translate3d(1px,0,0) scale(.995)}.task-dot{display:inline-block;width:9px;height:9px;border-radius:50%;background:var(--color-accent);box-shadow:0 0 0 4px rgba(82,110,110,.08)}.task-dot.overdue{background:#8a5c20;box-shadow:0 0 0 4px rgba(138,92,32,.08)}.task-dot.muted{background:#9aa3a5;box-shadow:none}.overdue{color:#8a5c20}.task-action{color:var(--color-accent)}.mono{font-variant-numeric:tabular-nums}.wb-grid{display:grid;grid-template-columns:minmax(0,1.8fr) minmax(280px,1fr);gap:20px}.queue-search{display:flex;gap:8px;margin-bottom:18px}.case-preview-row{display:grid;grid-template-columns:minmax(170px,1.6fr) minmax(100px,1fr) minmax(105px,.8fr) 16px;align-items:center;gap:12px;min-height:62px;font-size:13px}.case-preview-row .mono{display:grid;gap:2px}.case-preview-row small,.notice-preview small{color:var(--color-text-secondary);font-size:11px}.section-footer{display:flex;justify-content:space-between;align-items:center;padding-top:14px;color:var(--color-text-secondary);font-size:12px}.notice-preview{display:flex;align-items:flex-start;gap:12px;padding:14px 4px}.notice-preview .task-dot{flex:none;margin-top:5px}.notice-preview span:last-child{display:grid;gap:4px}.quick-links{display:flex;flex-wrap:wrap;gap:8px;padding-top:14px}.quick-links h2{width:100%;margin:0;font-size:13px;color:var(--color-text-secondary)}.quick-links .el-button{margin:0}.section-error{color:var(--color-danger)}.section-error button{border:0;background:transparent;color:var(--color-accent);text-decoration:underline;cursor:pointer}.skeleton-rows{padding:30px 8px;color:var(--color-text-secondary)}.empty-copy{display:grid;min-height:170px;place-items:center;padding:16px 8px;color:var(--color-text-secondary);text-align:center}.empty-copy img{width:132px;max-height:112px;object-fit:contain;filter:grayscale(1);opacity:.62}.empty-copy p{margin:0}
.task-row,.case-preview-row,.notice-preview{animation:list-arrive 320ms cubic-bezier(.16,1,.3,1) both}.task-row:nth-child(2),.case-preview-row:nth-child(2),.notice-preview:nth-of-type(2){animation-delay:35ms}.task-row:nth-child(3),.case-preview-row:nth-child(3),.notice-preview:nth-of-type(3){animation-delay:70ms}.task-row:nth-child(4),.case-preview-row:nth-child(4),.notice-preview:nth-of-type(4){animation-delay:105ms}.task-row:nth-child(5),.case-preview-row:nth-child(5){animation-delay:140ms}.task-row:nth-child(6),.case-preview-row:nth-child(6){animation-delay:175ms}
@keyframes blueprint-drift-in{from{opacity:0;transform:translate3d(28px,8px,0)}to{opacity:.45;transform:translate3d(0,0,0)}}@keyframes axis-in{from{opacity:0;transform:scaleX(.72)}to{opacity:1;transform:scaleX(1)}}@keyframes list-arrive{from{opacity:0;transform:translate3d(0,6px,0)}to{opacity:1;transform:translate3d(0,0,0)}}
@media(max-width:1250px){.wb-grid{grid-template-columns:1fr}.task-row{grid-template-columns:12px 1fr 1fr auto}.task-row span:nth-child(4){display:none}}@media(max-width:700px){.workbench-hero{min-height:180px}.hero-copy{padding:16px;background:rgba(255,255,255,.74)}.engineering-bike{right:-24%;width:520px;opacity:.25}.wb-section{padding:18px}.task-row{grid-template-columns:12px 1fr auto}.task-row .mono{display:none}.case-preview-row{grid-template-columns:1fr auto}.case-preview-row>span:nth-child(2),.case-preview-row>span:last-child{display:none}}
@media(prefers-reduced-transparency:reduce){.hero-copy{background:#fff;backdrop-filter:none}}@media(prefers-reduced-motion:reduce){.engineering-bike,.hero-axis,.task-row,.case-preview-row,.notice-preview{animation:none}.task-row:hover,.case-preview-row:hover,.notice-preview:hover{transform:none}}
</style>
